const date = $input.first().json.body?.date;
if (!date) throw new Error("Missing date in request body");

// 1. Idempotency Check (Part 2)
const existing = ((await (await fetch('http://mock-api:4100/report')).json()).data || []).find(r => String(r.date) === String(date));
if (existing) return [{ json: existing }];

// 2. KL Timezone UTC+8 Bounds (Fault 3)
const fromMs = Date.parse(`${date}T00:00:00+08:00`);
const fromISO = new Date(fromMs).toISOString();
const toISO = new Date(fromMs + 86400000).toISOString();

// 3. Dynamic Exchange Rates (Fault 2)
const rates = (await (await fetch('http://mock-api:4100/rates')).json()).rates || { MYR: 1, USD: 4.42, SGD: 3.28 };

// 4. Paginated Orders Fetch (Fault 1)
let page = 1, totalPages = 1, orders = [];
do {
  const res = await (await fetch(`http://mock-api:4100/orders?from=${fromISO}&to=${toISO}&page=${page}&per_page=100`)).json();
  orders.push(...(res.data || []));
  totalPages = res.total_pages || 1;
  page++;
} while (page <= totalPages);

// 5. Revenue Aggregation & Submission
const totalMYR = Number(orders.reduce((sum, o) => sum + o.amount * (rates[o.currency] || 1), 0).toFixed(2));
const report = { date: String(date), order_count: orders.length, total_myr: totalMYR };

const posted = await (await fetch('http://mock-api:4100/report', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify(report)
})).json();

return [{ json: posted }];
